contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool doDeposit, uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);

        if (doDeposit) {
            c.depositsCount();
        }

        uint cBalBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint cBalAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balAfter = address(this).balance;

        assert(
            (reverted && cBalAfter == cBalBefore && countAfter == countBefore && balAfter == balBefore) ||
            (!reverted && cBalAfter == 0 && countAfter == countBefore && balAfter == balBefore + cBalBefore)
        );
    }

    receive() external payable {}
}

