pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(bool doDeposit, uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        if (doDeposit) {
            c.depositsCount();
        }
        uint cBalBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint balBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint cBalAfter = address(c).balance;
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        uint balAfter = address(this).balance;
        assertTrue((reverted && cBalAfter == cBalBefore && countAfter == countBefore && balAfter == balBefore) ||
            (!reverted && cBalAfter == 0 && countAfter == countBefore && balAfter == balBefore + cBalBefore));
    }

    function testFuzz_run(bool doDeposit, uint256 depositAmount) public {
        _run(doDeposit, depositAmount);
    }

    receive() external payable {}
}
